// Tile index map for public/assets/sprites/tileset.png (128x128 px, 8 columns x 8 rows of 16x16).
// Index = row * 8 + column. The layout is split into four 4x4 quadrants so that each
// quadrant can be generated by ONE image prompt (see docs/ART_PROMPTS.md).
//
//   Quadrant A (cols 0-3, rows 0-3): terrain
//   Quadrant B (cols 4-7, rows 0-3): nature (2x2 trees + props)
//   Quadrant C (cols 0-3, rows 4-7): village / buildings
//   Quadrant D (cols 4-7, rows 4-7): reserved for later

export const T = {
  // --- A: terrain ---
  GRASS: 0, GRASS2: 1, FLOWERS: 2, TALLGRASS: 3,
  PATH: 8, PATH2: 9, SAND: 10, BRIDGE: 11,
  WATER: 16, WATER2: 17, SHALLOW: 18, COBBLE: 19,
  DARKGRASS: 24, MUD: 25, GRAVEL: 26, DIRT: 27,

  // --- B: nature ---
  TREE_TL: 4, TREE_TR: 5, PINE_TL: 6, PINE_TR: 7,
  TREE_BL: 12, TREE_BR: 13, PINE_BL: 14, PINE_BR: 15,
  BUSH: 20, ROCK: 21, STUMP: 22, PEBBLES: 23,
  FENCE: 28, SIGN: 29, LOG: 30, MUSHROOMS: 31,

  // --- C: village ---
  ROOF_TOP: 32, ROOF_TOP_CHIMNEY: 33, ROOF_TOP_L: 34, ROOF_TOP_R: 35,
  ROOF: 40, ROOF_DORMER: 41, ROOF_L: 42, ROOF_R: 43,
  WALL: 48, WALL_WINDOW: 49, DOOR: 50, WALL_BEAM: 51,
  CRATE: 56, BARREL: 57, WELL: 58, HAY: 59,
};

// Tiles the player cannot walk through (applies to the ground + obstacles layers).
export const COLLIDING = [
  T.WATER, T.WATER2,
  T.TREE_BL, T.TREE_BR, T.PINE_BL, T.PINE_BR,
  T.BUSH, T.ROCK, T.STUMP, T.FENCE, T.SIGN, T.LOG,
  T.ROOF, T.ROOF_DORMER, T.ROOF_L, T.ROOF_R,
  T.WALL, T.WALL_WINDOW, T.DOOR, T.WALL_BEAM,
  T.CRATE, T.BARREL, T.WELL, T.HAY,
];

export const WATERY = [T.WATER, T.WATER2, T.SHALLOW];
